var stateDescriptor=Desc("scoped-counter",source:true);
registry.Register(stateDescriptor,()=>new TestModule(stateDescriptor,(c,t)=>{var values=c.Scope!.State("scoped-counter",c.NodeId,()=>new List<int>());values.Add(1);c.Scope.RequestRefresh(c.NodeId);return ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>{{"out",PortValue.Number(values.Count)}}));},()=>{}));
using(var lifetime=new ModuleExecutionScope()){
 var events=new List<ModuleNodeRequest>();int legacyEvents=0;lifetime.ProcedureRefreshRequested+=events.Add;lifetime.RefreshRequested+=_=>legacyEvents++;
 var first=new ProcedureDocument("first","first",[Node("same","scoped-counter")],[]);var second=first with{Id="second"};
 async Task<double> RunScoped(ProcedureDocument flow)=>(await engine.RunAsync(flow,".",scope:lifetime)).Nodes.Single().Outputs["out"].As<double>();
 Check(await RunScoped(first)==1,"First procedure initializes own state");Check(await RunScoped(second)==1,"Second procedure same node ID initializes separately");Check(await RunScoped(first)==2,"First procedure retains only its own state");
 Check(events.Select(e=>e.ProcedureId).SequenceEqual(new[]{"first","second","first"})&&events.All(e=>e.ScopeId==lifetime.Id&&e.NodeId=="same"),"Refresh events carry lifetime and owning procedure");Check(legacyEvents==0,"Scoped events never reach ambiguous legacy node-only observers");
 lifetime.ForProcedure("first").RemoveNode("scoped-counter","same");Check(await RunScoped(first)==1&&await RunScoped(second)==2,"Remove affects only owning procedure");
 lifetime.RetainProcedureNodes(new[]{("second","scoped-counter","same")});Check(await RunScoped(second)==3&&await RunScoped(first)==1,"Retention compares full procedure/module/node identity");
 using(lifetime.ForProcedure("first")){}Check(await RunScoped(second)==4,"Disposing a borrowed procedure view cannot dispose solution");
 var requests=new List<ModuleNodeRequest>();lifetime.ProcedureRunRequested+=requests.Add;lifetime.ForProcedure("second").RequestRun("same");Check(requests.Single().ProcedureId=="second","Run event selects exact owning procedure");
 using var other=new ModuleExecutionScope();Check(other.Id!=lifetime.Id&&other.ForProcedure("second").State("scoped-counter","same",()=>new List<int>()).Count==0,"New solution lifetime isolates identical flow/node IDs");
 lifetime.Dispose();bool expired=false;try{lifetime.ForProcedure("first").State("scoped-counter","same",()=>new List<int>());}catch(ObjectDisposedException){expired=true;}Check(expired,"Borrowed views reject writes after solution close");
}
